// Extract issue key, summary, and description text.
// Handles multiple possible shapes depending on Jira node settings:
// 1) simplifyOutput=true -> capitalized display keys directly on the item (Summary, Description)
// 2) raw Jira API shape -> nested under fields.summary / fields.description
// 3) description may be plain text OR Atlassian Document Format (ADF) JSON
const issue = $input.item.json;

const issueKey = issue.key || issue.id || 'UNKNOWN';
const summary = issue.Summary ?? issue.fields?.summary ?? issue.summary ?? '';

let rawDescription;
if (issue.Description !== undefined) {
  rawDescription = issue.Description;
} else if (issue.fields?.description !== undefined) {
  rawDescription = issue.fields.description;
} else {
  rawDescription = issue.description;
}

function adfToText(node) {
  if (!node) return '';
  if (typeof node === 'string') return node;
  let text = '';
  if (node.type === 'text' && node.text) {
    text += node.text;
  }
  if (Array.isArray(node.content)) {
    for (const child of node.content) {
      text += adfToText(child);
      if (child.type === 'paragraph' || child.type === 'listItem' || child.type === 'heading') {
        text += '\n';
      }
    }
  }
  return text;
}

let descriptionText = '';
if (!rawDescription) {
  descriptionText = '(No description provided)';
} else if (typeof rawDescription === 'string') {
  descriptionText = rawDescription;
} else if (typeof rawDescription === 'object') {
  descriptionText = adfToText(rawDescription).trim();
  if (!descriptionText) {
    descriptionText = '(Description present but could not be parsed from ADF format)';
  }
}

const formattedStory = `Story: ${issueKey} - ${summary}\n\n${descriptionText}`;

return [{
  json: {
    issueKey,
    summary,
    formattedStory
  }
}];

