const review = $('AC Review & Risk Agent').item.json.output;
const gaps = review.gaps || [];

let highCount = 0, mediumCount = 0, lowCount = 0;
for (const g of gaps) {
  if (g.severity === 'High') highCount++;
  else if (g.severity === 'Medium') mediumCount++;
  else if (g.severity === 'Low') lowCount++;
}

// Rule-based deterministic scoring:
// Start at 100. High severity gaps are heavily penalized so that even ONE High gap
// drops the score below the 80 threshold - keeping this consistent with the AC Review
// Agent's own rule that any High gap means 'Not Ready'.
let score = 100;
score -= highCount * 25;
score -= mediumCount * 8;
score -= lowCount * 3;
score = Math.max(0, Math.min(100, score));

const threshold = 80;
const readinessVerdict = score >= threshold ? 'Ready' : 'Not Ready';

return [{
  json: {
    readinessScore: score,
    threshold,
    readinessVerdict,
    highCount,
    mediumCount,
    lowCount
  }
}];

const review = $('AC Review & Risk Agent').item.json.output;
const qOut = $('Requirement Question Generator').item.json.output;
const score = $json;
const storyInfo = $('Format Jira Story Text').item.json;

const gaps = review.gaps || [];
const questions = qOut.questions || [];

let md = `*QA Readiness Report - ${storyInfo.issueKey}*\n\n`;
md += `*Readiness Score:* ${score.readinessScore} / 100 (threshold: ${score.threshold})\n`;
md += `*Readiness Verdict:* ${score.readinessVerdict}\n`;
md += `*AC Review Verdict:* ${review.verdict}  |  *Overall Risk Level:* ${review.overallRiskLevel}\n\n`;
md += `*Summary:* ${review.summary}\n\n`;

if (gaps.length === 0) {
  md += `No gaps or risks identified in the Acceptance Criteria.\n\n`;
} else {
  md += `*Identified Gaps / Risks (${score.highCount} High, ${score.mediumCount} Medium, ${score.lowCount} Low):*\n`;
  for (const g of gaps) {
    md += `- [${g.id}] (${g.category} / ${g.severity}) ${g.acReference} -> ${g.description}\n`;
  }
  md += `\n*Clarifying Questions for Product Owner:*\n`;
  for (const q of questions) {
    md += `- [${q.id}] (ref ${q.relatedGapId}) ${q.question}\n`;
  }
  md += `\n`;
}

if (score.readinessVerdict === 'Not Ready') {
  md += `_This story is NOT recommended for sprint planning until the above gaps are resolved with the Product Owner._\n\n`;
} else {
  md += `_This story meets the Definition of Ready threshold and may be pulled into sprint planning._\n\n`;
}

md += `_This report was generated automatically by the Story -> QA Readiness workflow._`;

return [{
  json: {
    issueKey: storyInfo.issueKey,
    commentBody: md,
    readinessScore: score.readinessScore,
    readinessVerdict: score.readinessVerdict,
    acVerdict: review.verdict,
    overallRiskLevel: review.overallRiskLevel,
    summary: review.summary,
    gaps,
    questions
  }
}];

const payload = $('Prepare Jira Comment').item.json;

let md = `**QA Readiness Report Posted to ${payload.issueKey}**\n\n`;
md += `**Readiness Score:** ${payload.readinessScore} / 100\n`;
md += `**Readiness Verdict:** ${payload.readinessVerdict}\n`;
md += `**AC Review Verdict:** ${payload.acVerdict}  |  **Overall Risk Level:** ${payload.overallRiskLevel}\n\n`;
md += `**Summary:** ${payload.summary}\n\n`;

if (payload.gaps.length === 0) {
  md += `No gaps or risks identified.\n`;
} else {
  md += `**Gaps / Risks:**\n`;
  for (const g of payload.gaps) {
    md += `- [${g.id}] (${g.category} / ${g.severity}) ${g.acReference} -> ${g.description}\n`;
  }
  md += `\n**Clarifying Questions:**\n`;
  for (const q of payload.questions) {
    md += `- [${q.id}] ${q.question}\n`;
  }
}

md += `\n_Full report has also been added as a comment on ${payload.issueKey} in Jira._`;

return [{ json: { output: md, issueKey: payload.issueKey, readinessScore: payload.readinessScore, readinessVerdict: payload.readinessVerdict } }];
